package au.aumanet.app;

import org.json.*;
import java.util.*;
import java.security.PublicKey;

/** Explicit USB-administration configuration, never learned from DHCP/ARP/SSID/UDP. */
final class GatewayBindingConfig {
    static final class Node{final String id,run,publicKeyDerHex,publicKeySha256;final PublicKey publicKey;final GatewayLanProfile lan;
        Node(String id,String run){this(id,run,"","",null);}
        private Node(String id,String run,String der,String pin,PublicKey key){this(id,run,der,pin,key,null);}
        private Node(String id,String run,String der,String pin,PublicKey key,GatewayLanProfile lan){GatewayGrantCodec.identifier(id);GatewayGrantCodec.identifier(run);this.id=id;this.run=run;publicKeyDerHex=der;publicKeySha256=pin;publicKey=key;this.lan=lan;}
        static Node pinned(String id,String run,String der,String pin)throws Exception{return new Node(id,run,der,pin,GatewayBootCodec.nodeKey(der,pin));}
        Node withLan(GatewayLanProfile lan){return new Node(id,run,publicKeyDerHex,publicKeySha256,publicKey,lan);}
        Node observedRun(String current){return new Node(id,current,publicKeyDerHex,publicKeySha256,publicKey,lan);}
    }
    static final class Binding{final String phone,attachment,address,mac;final long generation;Binding(String phone,String attachment,String address,String mac,long generation){this.phone=phone;this.attachment=attachment;this.address=address;this.mac=mac;this.generation=generation;}}
    final String group,owner,schema;private final String explicitRadioRelay;final long epoch;final List<Node> nodes;final List<Binding> bindings;
    private GatewayBindingConfig(String schema,String group,String owner,long epoch,List<Node> nodes,List<Binding> bindings,String relay){this.explicitRadioRelay=relay;this.schema=schema;this.group=group;this.owner=owner;this.epoch=epoch;this.nodes=Collections.unmodifiableList(nodes);this.bindings=Collections.unmodifiableList(bindings);}
    boolean routed(){return schema.equals("aumanet.gateway-config.v4");}
    boolean bootRecovery(){return schema.equals("aumanet.gateway-config.v2")||schema.equals("aumanet.gateway-config.v3")||routed();}
    String radioRelayNode(){return schema.equals("aumanet.gateway-config.v3")||routed()?explicitRadioRelay:ownerAttachment();}
    String localGateway(){if(!routed())return "10.77.0.1";for(Node n:nodes)if(n.id.equals(ownerAttachment()))return n.lan.gateway;throw new SecurityException("Checked local LAN unavailable");}
    byte[] bind(Node node,Binding b,long sequence,long issued,long expires,long generation,boolean remove){return routed()?GatewayGrantCodec.routedBind(group,epoch,node.id,node.run,sequence,issued,expires,b.attachment,b.address,b.mac,generation,remove):GatewayGrantCodec.bind(group,epoch,node.id,node.run,sequence,issued,expires,b.attachment,b.address,b.mac,generation,remove);}
    String ownerAttachment(){for(Binding binding:bindings)if(binding.phone.equals(owner))return binding.attachment;throw new IllegalStateException("Configured owner attachment is unavailable");}
    static void keys(JSONObject value,String... names)throws Exception{Set<String> keys=new HashSet<>();value.keys().forEachRemaining(keys::add);if(!keys.equals(new HashSet<>(Arrays.asList(names))))throw new IllegalArgumentException("Unexpected gateway configuration fields");}
    static GatewayBindingConfig parse(JSONObject value,GatewayOwnerAuthority.Scope scope)throws Exception{
        String schema=GroupNameMetadata.string(value,"schema");boolean routed=schema.equals("aumanet.gateway-config.v4"),explicit=schema.equals("aumanet.gateway-config.v3")||routed;if(explicit)keys(value,"schema","groupId","epoch","ownerPin","nodes","bindings","radioRelayNode");else keys(value,"schema","groupId","epoch","ownerPin","nodes","bindings");String group=GroupNameMetadata.string(value,"groupId"),owner=GroupNameMetadata.string(value,"ownerPin");boolean boot=schema.equals("aumanet.gateway-config.v2")||explicit;long epoch=GroupNameMetadata.number(value,"epoch");if(!schema.equals("aumanet.gateway-config.v1")&&!boot||!group.equals(scope.group)||!owner.equals(scope.self)||epoch!=scope.epoch)throw new SecurityException("Gateway configuration does not match the saved owner");
        JSONArray rawNodes=value.getJSONArray("nodes"),rawBindings=value.getJSONArray("bindings");if(rawNodes.length()!=2||(!routed&&rawBindings.length()!=2)||routed&&(rawBindings.length()<2||rawBindings.length()>4))throw new IllegalArgumentException("Invalid bounded checked node/client count");
        List<Node> nodes=new ArrayList<>();Set<String> nodeIds=new HashSet<>(),nodePins=new HashSet<>(),networks=new HashSet<>();for(int i=0;i<2;i++){JSONObject row=rawNodes.getJSONObject(i);if(routed)keys(row,"id","run","publicKeyDerHex","publicKeySha256","lanGrant");else if(boot)keys(row,"id","run","publicKeyDerHex","publicKeySha256");else keys(row,"id","run");Node node=boot?Node.pinned(GroupNameMetadata.string(row,"id"),GroupNameMetadata.string(row,"run"),GroupNameMetadata.string(row,"publicKeyDerHex"),GroupNameMetadata.string(row,"publicKeySha256")):new Node(GroupNameMetadata.string(row,"id"),GroupNameMetadata.string(row,"run"));if(!nodeIds.add(node.id)||boot&&!nodePins.add(node.publicKeySha256))throw new IllegalArgumentException("Gateway nodes and pinned keys must be distinct");if(routed){node=node.withLan(GatewayLanProfile.read(row.getJSONObject("lanGrant"),group,epoch,owner,node.id));if(!networks.add(node.lan.network))throw new SecurityException("Overlapping checked node LANs");}nodes.add(node);}
        List<Binding> bindings=new ArrayList<>();Map<String,Integer> counts=new HashMap<>();Set<String> phones=new HashSet<>(),addresses=new HashSet<>(),attachments=new HashSet<>(),macs=new HashSet<>();for(int i=0;i<rawBindings.length();i++){JSONObject row=rawBindings.getJSONObject(i);keys(row,"phonePin","attachmentNode","ipv4","mac","generation");Binding binding=new Binding(GroupNameMetadata.string(row,"phonePin"),GroupNameMetadata.string(row,"attachmentNode"),GroupNameMetadata.string(row,"ipv4"),GroupNameMetadata.string(row,"mac"),GroupNameMetadata.number(row,"generation"));if(!scope.approved.contains(binding.phone)||!phones.add(binding.phone)||!addresses.add(binding.address)||!nodeIds.contains(binding.attachment)||!routed&&!attachments.add(binding.attachment)||!macs.add(binding.mac))throw new IllegalArgumentException("Gateway bindings require distinct approved phones and checked addresses/MACs");if(routed){int count=counts.getOrDefault(binding.attachment,0)+1;if(count>2)throw new SecurityException("Local client capacity exceeded");counts.put(binding.attachment,count);for(Node node:nodes)if(node.id.equals(binding.attachment)&&!node.lan.contains(binding.address))throw new SecurityException("Client address is outside its authorized node LAN");}for(Node node:nodes){if(routed)GatewayGrantCodec.routedBind(group,epoch,node.id,node.run,1,100,130,binding.attachment,binding.address,binding.mac,binding.generation,false);else GatewayGrantCodec.bind(group,epoch,node.id,node.run,1,100,130,binding.attachment,binding.address,binding.mac,binding.generation,false);}bindings.add(binding);}
        if(!phones.contains(owner))throw new IllegalArgumentException("Gateway bindings must include the owner phone");String relay=explicit?GroupNameMetadata.string(value,"radioRelayNode"):"";if(explicit&&!nodeIds.contains(relay))throw new IllegalArgumentException("Radio relay must identify one checked pinned node");return new GatewayBindingConfig(schema,group,owner,epoch,nodes,bindings,relay);
    }
    void liveOwner(GatewayOwnerAuthority.Scope scope){scope.selectedGatewayWifi();Binding own=null;for(Binding row:bindings)if(row.phone.equals(owner))own=row;if(own==null||!own.address.equals(scope.address)||!group.equals(scope.group)||epoch!=scope.epoch||!owner.equals(scope.self))throw new IllegalStateException("The selected owner Wi-Fi address does not match its checked attachment");}
}
